        raise ValueError("Input must be in the range 1 to 50, inclusive.")

    factorial_cache = dict()
    factorial_cache[1] = 1
    factorial = 1

    sum_factorials = 0

    for i in range(2, n + 1):
        if i in factorial_cache:
            factorial = factorial_cache[i]
        else:
