def optimize_seating(M: int, N: int, K: int, L: int, D: int, chatting_pairs: list) -> (str, str):
    def boarding_seat_density(aisle_x, aisle_y):
        hh = [(i, e[0]) for i, e in enumerate(chatting_pairs) if (e[0] == aisle_x or e[2] == aisle_x)]
        ll = [(i, e[1]) for i, e in enumerate(chatting_pairs) if (e[1] == aisle_y or e[3] == aisle_y)]
        return sum(hh) + sum(ll)

    winning = (0, 0)
    for aimx in range(K+2):
        for aimy in range(L+2):
            if boarding_seat_density(aimx, aimy) > winning[1]:
