def count_passing_ways(n: int, m: int) -> int:
    if n <= 0 or m <= 0:
        raise ValueError("Number of students and passes must be positive integers.")

    if m % 2 == 0:
        return 1  # Even number of passes, always one way to return

    dp = [0] * (m + 1)
    dp[0] = 1  # The initial position is considered as one way

    for i in range(1, m + 1):
        if i % 2 == 1:
            dp[i % 2] = 2
        else:
            dp[i % 2] = (dp[(i - 1) % 2] + dp[(i - 2) % 2]) % (10 ** 9 + 7)

    return dp[m]

def max_happiness(n: int, m: int, items: List[Tuple[int, int]]) -> int:
    if not n or not m or not items:
        raise ValueError("Invalid input parameters")

    # Initialize a 2D array to store the maximum happiness of subsets of items within the current budget
    dp = [[0] * (n + 1) for _ in range(m + 1)]

    # Fill the DP table
    for i in range(1, m + 1):
        for j in range(1, n + 1):
            item_price, item_importance = items[i - 1][0], items[i - 1][1]
            if item_price > j:
                dp[i][j] = dp[i - 1][j]
            else:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - item_price] + item_importance)

    return dp[m][n]

