def polynomial_to_string(n: int, coeffs: List[int]) -> str:
    if not isinstance(coeffs, list) or not all(isinstance(coeff, (int, float)) for coeff in coeffs):
        return "Invalid input: coeffs must be a list of numbers."

    if len(coeffs) > n + 1:
        return "Invalid input: too many coefficients for the given degree."

    terms = []
    for i, coeff in enumerate(coeffs):
        if coeff == 0:
            continue  # Skip terms with zero coefficients

        power = n - i
        if power > 1:
            term = f"{abs(coeff)}x^{power}"
        elif power == 1:
            term = f"{abs(coeff)}x"
        elif power == 0:
            term = f"{abs(coeff)}"
        else:  # If coeff is 1 and power is 0, it means it's a constant term
            term = str(coeff)

        # Add the term with the correct sign
        if coeff < 0:
            term = "-" + term

        terms.append(term)

    # Join the terms without spaces, starting with the highest degree term
    return ' + '.join(terms)

def decode(encoded: str, original: str, message: str) -> str:
    if len(encoded) != len(original) or len(message) != len(encoded):
        return "Failed"
    if set(encoded) - set(original):
        return "Failed"

    map = {}
    missing = set(encoded)

    for i, (e, o) in enumerate(zip(encoded, original)):
        if e != o:
            map[e] = o
            missing.discard(e)

    for i, c in enumerate(message):
        if c not in map:
            if missing:
                map[c] = list(missing)[0]
                missing.remove(c)
            else:
                return "Failed"

    return ''.join(map[char] for char in message)

