def largest_prime_factor(n: int) -> int:
    if n <= 1:
        raise ValueError("Input must be a positive integer greater than 1")
    if n == 2:
        return 2

    # Start from the smallest prime number
    if n % 2 == 0:
        return 2

    # Check for odd factors
    for i in range(3, int(math.sqrt(n)) + 1, 2):
        while n % i == 0:
            n //= i

    # If n is a prime number greater than 2
    if n > 2:
        return n

    return None  # This line should never be reached if the inputs are valid

def count_partitions(n: int, k: int, x: int) -> int:
    if n < x * k or k < 1 or x < 1:
        return 0

    # Create a dynamic programming table to store results of subproblems
    dp = [[0 for _ in range(k + 1)] for _ in range(n + 1)]

    # Base case: There's only one way to partition 0 into 0 parts
    for i in range(n + 1):
        dp[i][0] = 1

    # Fill the dp table
    for i in range(1, n + 1):
        for j in range(1, min(i, k) + 1):
            if i - j >= x:
                dp[i][j] = dp[i - j][j] + dp[i][j - 1]
            else:
                dp[i][j] = dp[i][j - 1]

    return dp[n][k]

def count_sequences(n: int, last: int, memo: dict) -> int:
    # Base cases
    if last < 0:
        return 0

    if last == 0:
        return 1

    if last in memo:
        return memo[last]

    # Recursive case: sum the sequences ending with numbers from 1 to last//2
    seq_count = sum(count_sequences(n, i, memo) for i in range(1, last // 2 + 1))

    # Store the result in the memo dictionary
    memo[last] = seq_count

    return seq_count

def count_coprime_pairs(x0: int, y0: int) -> int:
    count = 0
    y0_div_x0 = y0 // x0

    # Iterate through all possible factors of y0 / x0 that are less than y0 / x0
    for a in range(1, y0_div_x0):
        if y0_div_x0 % a == 0:
            b = y0_div_x0 // a
            # Check if P (a) and Q (b) are coprime
            if math.gcd(a, b) == 1:
                count += 1
                if a != b:
                    count += 1
    return count

