def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Args:
    num (int): The integer to check for primality.

    Returns:
    bool: True if `num` is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num == 2 or num == 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    # Initialize a set to keep track of unique numbers
    unique_numbers = set()

    # Function to perform BFS
    def bfs():
        current_number = str(n)
        queue = [current_number]
        length = len(current_number)
        unique_numbers.add(current_number)  # Add the original number to the set

        while queue:
            current_number = queue.pop(0)
            length = len(current_number)
            for i in range(length):
                for x, y in rules:
                    if current_number[i] == str(x):
                        new_number = current_number[:i] + str(y) + current_number[i+1:]
                        if new_number not in unique_numbers:
                            unique_numbers.add(new_number)
                            queue.append(new_number)

    # Perform BFS
    bfs()

    # Return the count of unique numbers
    return len(unique_numbers)

