            current_player_score += 1
        elif char == 'L':
            current_opponent_score += 1

        if current_player_score == system:
            score = f"{current_player_score}:{current_opponent_score}"
            if current_player_score - 2 >= current_opponent_score or current_opponent_score - 2 >= current_player_score - 2:
                scores.append(score)
                padding = system - current_player_score
            if padding > 0:
                padding -= 1
            current_player_score = 0
            current_opponent_score = 0

        elif current_opponent_score == system:
