class Solution:
    def catalan_number(self, n: int) -> int:
        if n < 0:
            raise ValueError("n must be non-negative")
        catalan = [0] * (n + 1)
        catalan[0], catalan[1] = 1, 1
        for i in range(2, n + 1):
            catalan[i] = sum(catalan[j] * catalan[i - j - 1] for j in range(i))
        return catalan[n]

