def max_herb_value(T: int, M: int, herbs: List[Tuple[int, int]]) -> int:
    if not herbs:
        return 0

    # Initialize a 2D list to store the maximum value that can be obtained
    dp = [[0] * (T + 1) for _ in range(M + 1)]

    # Fill the dp table
    for i in range(1, M + 1):
        for j in range(1, T + 1):
            # If the time taken to pick upto ith herb and jth time is within the limit
            if herbs[i - 1][0] <= j:
                # We have two choices: either to pick the herb or not
                # If not picked, we take the value from the previous herb
                # If picked, we add the value and move the time window
                dp[i][j] = max(dp[i - 1][j], herbs[i - 1][1] + dp[i - 1][j - herbs[i - 1][0]])
            else:
                # If time taken to pick upto ith herb and jth time exceeds the limit, we can't pick the herb
                dp[i][j] = dp[i - 1][j]

    # The maximum value that can be obtained within the time limit
    return dp[M][T]

