def min_remaining_space(V: int, n: int, volumes: List[int]) -> int:
    # Initialize a 2D list to store the maximum volume for subsets of items
    dp = [[0] * (V + 1) for _ in range(n + 1)]

    # Build up the dynamic programming table
    for i in range(1, n + 1):
        for j in range(1, V + 1):
            if volumes[i - 1] <= j:
                dp[i][j] = max(dp[i - 1][j], dp[i - 1][j - volumes[i - 1]] + volumes[i - 1])
            else:
                dp[i][j] = dp[i - 1][j]

    # The minimum remaining space is the difference between the box's total volume and the maximum occupied volume
    min_remaining = V - dp[n][V]
    return min_remaining

