def vigenere_decrypt(key: str, ciphertext: str) -> str:
    if not key.isalpha() or not ciphertext.isalpha():
        raise ValueError("Key and ciphertext must only contain alphabetic characters.")
    if len(key) != len(ciphertext):
        raise ValueError("Key and ciphertext must be the same length.")

    key_length = len(key)
    key_dict = {char: (key.index(char) + ord('A')) % 26 for char in key}
    decoded_text = []

    for i, char in enumerate(ciphertext):
        if char.isalpha():
            decrypted_text.append(chr((ord(char) + key_dict[char]) % 26 + ord('A')))
        else:
            decrypted_text.append(char)

    return ''.join(decoded_text)

