def next_permutation(perm: list) -> bool:
    # Find the first position from the right where perm[i] < perm[i+1]
    for i in range(len(perm) - 2, -1, -1):
        if perm[i] < perm[i + 1]:
            # Find the rightmost element in perm[i+1:] that is greater than perm[i]
            for j in range(len(perm) - 1, i, -1):
                if perm[j] > perm[i]:
                    # Swap perm[i] and perm[j]
                    perm[i], perm[j] = perm[j], perm[i]
                    break
            # Reverse the elements in perm[i+1:] to get the next permutation
            perm[i + 1:] = sorted(perm[i + 1:])
            return True
    # If no such pair is found, the last permutation is reached
    return False

def min_groups(w, n, prices):
    if w <= 0 or n <= 0:
        raise ValueError("W and n must be positive integers.")
    if n > len(prices):
        raise ValueError("The number of souvenirs must be less than or equal to the number of prices.")
    if not all(isinstance(price, int) for price in prices):
        raise ValueError("All price elements must be integers.")
    if not all(price >= 0 for price in prices):
        raise ValueError("All price elements must be non-negative.")

    prices.sort()
    group_count = 0
    current_price = 0

    for price in prices:
        if current_price + price > w:
            group_count += 1
            current_price = 0
        current_price += price

    if current_price > 0:
        group_count += 1

    return group_count

def hanoi_double_iterative(n: int) -> int:
    # Base case: If there is only one pair of discs, return 2 moves
    if n == 1:
        return 2

    # Base case: If there are two pairs of discs, return 6 moves
    if n == 2:
        return 6

    # Base case: If there are three pairs of discs, return 14 moves
    if n == 3:
        return 14

    # Recursive case: Calculate the minimum number of moves using the formula
    total_moves = 3 * (2 ** (n - 1)) - 1

    return total_moves
